//! Raw bindings to libopenmpt and `libopenmpt_ext`.
//!
//! The item names come from the C headers, so they do not follow the Rust
//! naming convention. `bindings.rs` is generated by `scripts/regen-bindings.sh`
//! and is not edited by hand.

// The names are the C identifiers. A rename would hide them from a reader who
// compares the wrapper against the header. The `unsafe_code` expectation covers
// the `unsafe extern` blocks that bindgen emits; every call into them stays in
// `openmpt-ext`. Bindgen also writes `#[allow]` attributes, so this crate cannot
// use the workspace rule that requires `#[expect]`.
#![expect(
    unsafe_code,
    non_camel_case_types,
    clippy::allow_attributes,
    reason = "the generated bindings carry C names and `#[allow]` attributes"
)]

/// Git tag of the vendored libopenmpt tree.
pub const PIN_TAG: &str = env!("OPENMPT_EXT_SYS_PIN_TAG");
/// Git commit of the vendored libopenmpt tree.
pub const PIN_COMMIT: &str = env!("OPENMPT_EXT_SYS_PIN_COMMIT");
/// SVN revision in the vendor commit message.
pub const PIN_SVN_REVISION: &str = env!("OPENMPT_EXT_SYS_PIN_SVN_REVISION");
/// SVN branch that the vendor commit comes from.
pub const PIN_SVN_URL: &str = env!("OPENMPT_EXT_SYS_PIN_SVN_URL");
/// Commit date of the vendor tree, in ISO 8601.
pub const PIN_SVN_DATE: &str = env!("OPENMPT_EXT_SYS_PIN_SVN_DATE");

include!("bindings.rs");
